-- Add D&D 5e stats (STR, DEX, CON, INT, WIS, CHA on 1-20 scale) to all matto_characters,
-- add win_stat (+1 for winners) and lose_stat (-1 for last place) to all matto_themes,
-- and create matto_stat_changes log table for reversible stat updates.

ALTER TABLE matto_characters ADD COLUMN str INTEGER NOT NULL DEFAULT 10;
ALTER TABLE matto_characters ADD COLUMN dex INTEGER NOT NULL DEFAULT 10;
ALTER TABLE matto_characters ADD COLUMN con INTEGER NOT NULL DEFAULT 10;
ALTER TABLE matto_characters ADD COLUMN int INTEGER NOT NULL DEFAULT 10;
ALTER TABLE matto_characters ADD COLUMN wis INTEGER NOT NULL DEFAULT 10;
ALTER TABLE matto_characters ADD COLUMN cha INTEGER NOT NULL DEFAULT 10;

ALTER TABLE matto_themes ADD COLUMN win_stat TEXT NOT NULL DEFAULT 'wis';
ALTER TABLE matto_themes ADD COLUMN lose_stat TEXT NOT NULL DEFAULT 'cha';

CREATE TABLE IF NOT EXISTS matto_stat_changes (
  day TEXT NOT NULL,
  character_id INTEGER NOT NULL REFERENCES matto_characters(id),
  stat TEXT NOT NULL CHECK (stat IN ('str', 'dex', 'con', 'int', 'wis', 'cha')),
  delta INTEGER NOT NULL,
  PRIMARY KEY (day, character_id, stat)
);
CREATE INDEX IF NOT EXISTS matto_stat_changes_day ON matto_stat_changes(day);

